import unittest
from candidate import filter_integers

class TestFilterIntegers(unittest.TestCase):
    def test_normal_case_with_integers(self):
        self.assertEqual(filter_integers([1, 2, 3, 4]), [1, 2, 3, 4])

    def test_normal_case_with_mixed_types(self):
        self.assertEqual(filter_integers(['a', 3.14, 5, True, None]), [5])

    def test_empty_list(self):
        self.assertEqual(filter_integers([]), [])

    def test_all_non_integers(self):
        self.assertEqual(filter_integers(['abc', 3.14, True, None]), [])

    def test_boundary_zero(self):
        self.assertEqual(filter_integers([0]), [0])

    def test_boundary_negative_numbers(self):
        self.assertEqual(filter_integers([-1, -2, -3]), [-1, -2, -3])

    def test_boundary_large_numbers(self):
        self.assertEqual(filter_integers([2**31 - 1, 2**31]), [2**31 - 1, 2**31])

    def test_none_input(self):
        with self.assertRaises(TypeError):
            filter_integers(None)

    def test_non_list_input(self):
        with self.assertRaises(TypeError):
            filter_integers("not a list")

    def test_list_with_nested_structures(self):
        self.assertEqual(filter_integers([1, [2, 3], {"a": 4}, (5,)]), [1])

    def test_list_with_floats_booleans(self):
        self.assertEqual(filter_integers([1.0, True, False, 2]), [1.0, 2])

    def test_list_with_bytes(self):
        self.assertEqual(filter_integers([b'1', 2]), [2])

    def test_list_with_complex_numbers(self):
        self.assertEqual(filter_integers([1+2j, 3]), [3])

    def test_list_with_decimal_integers(self):
        self.assertEqual(filter_integers([1000000000000000000, 999999999999999999]), [1000000000000000000, 999999999999999999])

    def test_list_with_multiple_identical_integers(self):
        self.assertEqual(filter_integers([2, 2, 2, 2]), [2, 2, 2, 2])
